import { useEffect, useRef } from "react";

export function usePrint() {
  const styleRef = useRef<HTMLStyleElement | null>(null);
  const printRef = useRef<HTMLButtonElement>(null);
  useEffect(() => {
    const style = document.createElement("style");
    style.textContent = `
        @media print {
          @page {
            size: var(--paper-width)mm auto;
            margin: 10mm;
          }
          body {
            visibility: hidden;
          }
          #print-container {
            visibility: visible;
            position: absolute;
            left: 0;
            top: 0;
            width: 100%;
          }
        }
      `;
    document.head.appendChild(style);
    styleRef.current = style;

    return () => {
      if (styleRef.current) {
        document.head.removeChild(styleRef.current);
        styleRef.current = null;
      }
    };
  }, []);
  useEffect(() => {
    if (printRef.current === null) {
      return;
    }
    printRef.current.focus();
    // Ctrl+P belongs to the receipt view itself, so it is deliberately not
    // behind `isScreenOwnedByDialog` — the printed result *is* the dialog.
    function printWebView(e: KeyboardEvent) {
      if (e.ctrlKey && e.key === "p") {
        document.documentElement.style.setProperty("--paper-width", `72`);
        window.print();
      }
    }
    window.addEventListener("keydown", printWebView);
    return () => {
      window.removeEventListener("keydown", printWebView);
    };
  }, [printRef]);
  return [printRef] as const;
}
